(window.LADDER_CARDS=window.LADDER_CARDS||{})["29·G"]=[{"q": "L_h(a, b) = h(½m((b − a)/h)² − V(a)). What is it?", "a": "the action of one step, from a to b", "w": ["the action of the whole path", "the energy at one tick", "the stepped momentum"], "why": "The step-action technique adds these over the ticks."}, {"q": "x_k appears in only two terms of the stepped action. Setting its partial slope to 0 gives …", "a": "m(x_{k+1} − 2x_k + x_{k−1})/h² = −V′(x_k)", "w": ["m(x_{k+1} − x_k)/h = −V′(x_k)", "x_{k+1} = x_k + h v_k", "m x″ = −V′(x)"], "why": "The step-action technique: the stepped law of motion."}, {"q": "As the tick h shrinks, the stepped law heads to …", "a": "mx″ = −V′(x), the action-to-force technique", "w": ["x′ = 0", "the plain step", "a law with no force"], "why": "The stepped bend heads to the second slope (23b)."}, {"q": "Sliding every body along together changes no step’s action. What is kept?", "a": "the stepped momentum, exactly, at every h", "w": ["the energy, exactly", "the stepped momentum, only for small h", "nothing, since time has holes"], "why": "The stepped-symmetry technique."}, {"q": "Why is energy not kept exactly by the stepped law?", "a": "stepped time slides only by whole ticks", "w": ["the stepped law has no symmetry at all", "energy needs a slide in space", "the plain step is used"], "why": "Energy goes with sliding the motion in time; there is no small slide in stepped time."}, {"q": "The stepped map (x_{k−1}, x_k) ↦ (x_k, x_{k+1}) has slope grid (0, 1; −1, ⋯). Its determinant is …", "a": "1, so it keeps area", "w": ["0, so it squashes area", "1 + h²ω²", "−1, so it flips"], "why": "The stepped-area technique; the area scale is |det| (28i)."}, {"q": "The plain step on a spring has grid (1, h; −hω², 1). Each step, area is multiplied by …", "a": "1 + h²ω²", "w": ["1", "1 − h²ω²", "h²ω²"], "why": "Its determinant: the plain step blows area, and energy, up."}, {"q": "For a spring, Q_k = x_k² + x_{k+1}² − c x_k x_{k+1} is …", "a": "kept exactly by the stepped law", "w": ["the energy, exactly", "kept only for small h", "doubled each step"], "why": "The stepped-energy technique: Q_{k+1} = Q_k."}, {"q": "A spring with ωh > 2, stepped. What happens?", "a": "the steps blow up", "w": ["it swings with the right period", "it stops", "it swings with a slightly short period"], "why": "c = 2 − ω²h² falls below −2."}, {"q": "x_k = cos kθ with 2 cos θ = c. What does it show?", "a": "the stepped spring swings exactly, with a slightly wrong period", "w": ["the stepped spring has the true period", "the energy is kept exactly", "the plain step is exact"], "why": "cos(k + 1)θ + cos(k − 1)θ = 2 cos θ cos kθ."}, {"q": "Has any measurement found a smallest tick of time?", "a": "no: it is open", "w": ["yes, the Planck time", "yes, about 2.5 × 10⁻¹⁹ s", "yes, a computer’s clock tick"], "why": "The shortest time measured is far longer than the smallest physics suggests, and no step has been seen."}];
