(window.LADDER_CARDS["40·now"]=window.LADDER_CARDS["40·now"]||[]).push(
 {"u":"40·now.1.1","q":"What does the core of a proof assistant do? Why does the trust shrink to the core?","a":"It checks each step of a proof against a fixed list of rules; the proof may be huge, and machines may help write it, but only the core decides, and the core is small enough for people to read","w":["It writes the proof by searching; the trust shrinks because the search is fast","It runs the program on test inputs; the trust rests on the tests","It stores every proof ever checked; the trust rests on the people who wrote them"],"why":"A small checker."},
 {"u":"40·now.2.1","q":"What did the compiler’s proof show? Which step of rung 40 is it, at full size?","a":"That every run of the compiled program is a run of the source, by a machine-checked proof; it is 40j’s demand, the compiling-keeps-runs technique of 40j2","w":["That the compiler stops on every program; it is 40e’s falling measure","That the compiled programs have no faults of any kind; it is 40h’s type check","That the compiler gives the same numbers as every other compiler; it is 40a’s assembler"],"why":"The proof is far longer than the compiler."},
 {"u":"40·now.3.1","q":"What was proved of the kernel? What did the proof cost?","a":"That the kernel of an operating system, the part that runs every other program, does what its precise description says, proved by machine in 2009; the cost was many years of work for a program of about ten thousand lines","w":["That the kernel has no faults of any kind; the proof took a day","That the kernel runs faster than any other; the cost was ten thousand machines","That every program run by the kernel is right; the proof was shorter than the kernel"],"why":"A kernel proved right."},
 {"u":"40·now.4.1","q":"What does a checked proof leave open? Why can the checker be small?","a":"The program meets its description, and the description may be wrong; and the core only checks each step against a fixed list of rules, so it is small while the proof is large","w":["Nothing: a checked proof means the program has no faults; the checker must be as large as the proof","Whether the proof was checked; the checker is small because it skips steps","Whether the program stops; the checker is small because proofs are short"],"why":"Both are rows of the step’s Moves to Watch Out For."});
/* end phase F und_r40 */
